p='index.html';s=open(p).read();s=s.replace('<div><label for="unitSelect">UNIT</label><select id="unitSelect"></select></div><button', '<div><label for="unitSelect">UNIT</label><select id="unitSelect"></select></div><div><label for="topicSelect">PREPARED TEXT</label><select id="topicSelect" aria-label="Prepared text"></select></div><button');s=s.replace('Pick a course and unit to get started.','Pick a course, unit and prepared text to read its notes.');s=s.replace('Turn this unit into something classroom-ready.','Optional: connect an AI provider for extra drafts. Prepared notes can be read without AI.');s=s.replace('AI can make mistakes. Review interpretations, quotations and sources before teaching.','Prepared notes are being added in syllabus order. Review every interpretation, quotation and source before teaching.');open(p,'w').write(s)
