s=s.replace("let content=entry[tab];$('#saveBtn').textContent=saved.some(x=>x.key===key()&&x.tab===tab)","let note=tab==='notes'?preparedNote():null;let content=note?note.text:entry[tab];$('#saveBtn').textContent=saved.some(x=>x.key===bookmarkKey()&&x.tab===tab)")
